import 'dart:io';


import 'dart:ui' as ui;

import 'package:flutter/material.dart';
import 'package:flutter/rendering.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:nothingness/models/audio_track.dart';
import 'package:nothingness/models/song_info.dart';
import 'package:nothingness/models/theme_id.dart';
import 'package:nothingness/services/playback_controller.dart';
import 'package:nothingness/theme/themes.dart';
import 'package:nothingness/widgets/heroes/dot_hero.dart';
import 'package:provider/provider.dart';
import 'package:shared_preferences/shared_preferences.dart';

import 'heroes/_test_helpers.dart';

Future<void> _captureToPng(
  WidgetTester tester, {
  required GlobalKey repaintKey,
  required String outputPath,
}) async {
  final boundary =
      repaintKey.currentContext!.findRenderObject() as RenderRepaintBoundary;

  // Ensure the layer tree is settled.
  await tester.pumpAndSettle();

  final image = await boundary.toImage(pixelRatio: 1.0);
  final byteData = await image.toByteData(format: ui.ImageByteFormat.png);
  final bytes = byteData!.buffer.asUint8List();

  final file = File(outputPath);
  await file.create(recursive: true);
  await file.writeAsBytes(bytes);
}

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();

  setUp(() {
    SharedPreferences.setMockInitialValues(<String, Object>{});
  });

  testWidgets('Dot song info overlay stays above the centered dot', (
    WidgetTester tester,
  ) async {
    const heroW = 800.0;
    const heroH = 512.0; // matches 0.32 heroFraction when surfaceHeight≈1600.

    const longArtist =
        'The Extremely Long Artist Name That Should Wrap Onto Multiple Lines';
    const longTitle =
        'A Surprisingly Long Song Title That Should Also Wrap Without Intersecting The Dot';

    // Max dot radius when the spectrum is hot.
    const spectrum = <double>[1.0, 1.0, 1.0, 0.0];

    SongInfo songInfo(String title, String artist) => SongInfo(
          track: AudioTrack(
            path: '/fixture/opussy',
            title: title,
            artist: artist,
          ),
          isPlaying: true,
          position: 0,
          duration: 1,
        );

    Future<void> pumpAndShoot(double textScale, String fileName) async {
      final provider = FakeAudioPlayerProvider(
        songInfo: songInfo(longTitle, longArtist),
        spectrumData: spectrum,
        isPlaying: true,
      );

      final dotConfig = DotScreenConfig(
        showSongInfo: true,
        textScale: textScale,
      );

      final repaintKey = GlobalKey();

      await tester.pumpWidget(
        ChangeNotifierProvider<PlaybackController>.value(
          value: provider,
          child: MaterialApp(
            theme: buildAppTheme(id: ThemeId.void_, brightness: Brightness.dark),
            home: Scaffold(
              body: Center(
                child: RepaintBoundary(
                  key: repaintKey,
                  child: SizedBox(
                    width: heroW,
                    height: heroH,
                    child: DotHero(config: dotConfig),
                  ),
                ),
              ),
            ),
          ),
        ),
      );

      await tester.pump();

      final outDir = Directory('.tmp/dot_hero_song_info');
      final outPath = '${outDir.path}/$fileName';
      await _captureToPng(tester, repaintKey: repaintKey, outputPath: outPath);

      expect(File(outPath).existsSync(), isTrue);
    }

    await pumpAndShoot(1.0, 'dot_song_info_normal_textScale_1.0.png');
    await pumpAndShoot(1.5, 'dot_song_info_max_textScale_1.5.png');
  });
}

